	title 'Event Manager        GS ROM 3.0'*********************************************************		               **                 Event Manager	               **		               ******************************************************************************************************************		               **              Copyright (C) 1985-1989	               **              Apple Computer, Inc.	               **              All Rights Reserved	               **		               ******************************************************************************************************************		               ** Change History		               **		               ** Version 2.0		               **		               **   Summer 86	         Cherly Ewy	               **		               **   Posting an illegal event code won't crash the      **   system.		               **		               **   December 23, 1986        SEG	               **		               **   EMStartup and EMShutdown were modified to save a   **   few bytes.  All	the PushWord #0 lines that were putting	 **   result space on	the stack were changed to PHA.     **   All the Get and	Set vector calls went through      **   glue routines, saving 3 bytes each for 45 bytes.   **   The NewHandle call was replaced with a call to     **   SpecialNewHandle.	               **		               **   February 27, 1987        Cheryl Ewy	               **		               **   Auto key events	are no longer posted unless        **   the queue is empty.	               **		               **   June 13, 1988            Joe Bo                    **                                                      **   Change locations for double click time ($2E to $38)**   and cursor flash rate ($2F to $2E) in battery ram. *                        *   		               **   Change EMStartUp & FakeMouse routines for only     **   ADB mouse to work with.                            **		               *** 29 Jun 88	Steven Glass** Two things were wrong in TickCount.  First the TickCnt * was being accessed with interrupts active and second, * if journaling was active, the journaling code was * called with the wrong direct page register.** 30 Jun 88	Steven Glass & Cheryl Ewy** Changed post event to look at AutoKeyLimit when* posting AutoKey events.** Added call SetAutoKeyLimit.** 21 Jan 89	Mensch* * Added kTrans table support in EMStartup, getNextEvent* and EventAvail.** Changed all ReadMouse calls to ReadMouse2 calls.* * 26 Jan 89	Mensch** Modified ktrans stuff to use the batery RAM location $5A* to get our resource ID.** 07 Feb 89	Mensch** Added GetKeyTranslation & SetKeyTranslation calls, modified the * startup stuff so it doesn't crash when you have picked none.* from the control panel for key remapping.** 13 Feb 89	Mensch** Fix emstartup to properly call the new setkeytranslation * routine.*****  3/20/89	Mark Cecys**  Added "MIDIInputPoll" in time-consuming routines. If assem directive "midi"*  is set to one, then polling will be assembled, otherwise if set to zero,*  no MIDI polling will be added. This is used by MidiTools which patches in*  its local cursor routines to prevent SCC over-run. (EM makefile has midi=0)*  The following PROC's are affected:*	PostEvent*	GetOSEvent*	DeQueue*	FillRecord*	Mouse** 26-Sep-90	Dave Lyons** Change SysDeathMgr to SysFailMgr to make it build* with current interfaces.** 24-Feb-91	Dave Lyons** Added EMStartUp call to UseCoolMousePos to set the mouse position from* MessageCenter message number 6.*********************************************************** 3-Jun-92	Dave Lyons** UseCoolMousePos (called by EMStartUp in both patch files) now puts the* mouse at (26,17) for 640 (or (13,17) in 320) if there's no Message #6.*********************************************************	include 'all.macros'	include '::sys.equs.asm'	MACRO&lab	PushPtr &addr&lab	dc.B $F4	dc.W (&addr)>>16	dc.B $F4	dc.W &addr	MENDEMVerNum	equ $0300	;V3.0*---------------------------------------------------------------* Constants*---------------------------------------------------------------True	equ $0001False	equ $0000EMTSNum	equ 6	;tool set num for Event MgrInitErr	equ $0601	;duplicate init callResetErr	equ $0602	;can't reset Event MgrActiveErr	equ $0603	;Event Mgr not activeCodeErr	equ $0604	;illegal event codeBtnErr	equ $0605	;illegal button numberSizeErr	equ $0606	;queue size too largeMemErr	equ $0607	;not enough mem for	queueQError	equ $0681	;fatal system error	- damaged queueHError	equ $0682	;fatal system error	- damaged Q handleTaskSig	equ $A55A	;signature word for	heartbeat taskKeyBufParam	equ $2B	;for ReadBParam callClickParam	equ $2E	;     "FlashParam	equ $2F	;     "MouseDown	equ 1	;event codeMouseUp	equ 2	;     "KeyDown	equ 3	;     "AutoKey	equ 5	;     "Update	equ 6	;     "Activate	equ 8	;     "Switch	equ 9	;     "DeskAccessory	equ 10	;     "BUpdate	equ $0040	;bit 6 setBActivate	equ $0100	;bit 8 setBSwitch	equ $0200	;bit 9 setBtn0bit	equ $0080	;used with modifiers fieldBtn1bit	equ $0040	;     "RepeatBit	equ $0800	;used with mod keys	latchMovedBit	equ $2000	;used with BStatMoveIntBit	equ $0002	;     "BtnIntBit	equ $0004	;     "JcTickCount	equ 0	;journal codeJcGetMouse	equ 1	;     "JcButton	equ 2	;     "JcEvent	equ 4	;     "EvtSize	equ 16	;size of event record in bytesEvtQSize	equ 18	;size of event record incl link fieldDefaultQ	equ 20	;default queue sizeMaxQ	equ 3639	;max queue sizeMsgOffset	equ 2	;offset to Message fieldWhenOffset	equ 6	;offset to When fieldWhereOffset	equ 10	;offset to Where fieldModsOffset	equ 14	;offset to Modifiers fieldEvtOffset	equ 2	;offset to event record from start of;		;event queue elementKindOffset	equ 4	;offset to WindowKind field in window*---------------------------------------------------------------* Hardware Equates*---------------------------------------------------------------MouseMode	equ $7F8	;mouse mode byteKeyLatch	equ $C000	;keyboard keypress latchKbdStrobe	equ $C010	;keyboard strobeModLatch	equ $C025	;keyboard modifiers	latchCardType	equ $C02D	;bit 4 specifies internal/external card*---------------------------------------------------------------* Event Manager Zero Page*---------------------------------------------------------------EMZBase	equ 0TempEvent	equ EMZBaseUserEvtPtr	equ TempEvent+16JResultPtr	equ UserEvtPtr+4SaveLink	equ JResultPtr+4TempLink	equ SaveLink+2TempPtr	equ TempLink+2TempBits	equ TempPtr+4SysEventMask	equ TempBits+2	;system event maskQHandle	equ SysEventMask+2	;handle for event queueQPtr	equ QHandle+4	;pointer to event queueQSize	equ QPtr+4	;max number of events in queueQHead	equ QSize+2	;link to first queue elementQTail	equ QHead+2	;link to last queue	elementCheckButton	equ QTail+2WhichButton	equ CheckButton+2GotSwitchCall	equ WhichButton+2	;1 if switch event pending, 0 if notWindowMgr	equ GotSwitchCall+2	;1 if Window Mgr init, 0 if notRemoveEvent	equ WindowMgr+2	;flag used by GetNextEventOSRemoveEvent	equ RemoveEvent+2	;flag used by GetOSEventGotMouse	equ OSRemoveEvent+2	;1 if mouse present, 0 if notExtMouse	equ GotMouse+2	;1 if external mouse, 0 if notMouseAdrs	equ ExtMouse+2	;original mouse vectorKBAdrs	equ MouseAdrs+4	;original keyboard vectorDAAdrs	equ KBAdrs+4	;original desk accesory vectorFBAdrs	equ DAAdrs+4	;original flush buffer vectorVBLAdrs	equ FBAdrs+4	;original VBL vectorKBufOn	equ VBLAdrs+4	;1 if keyboard buffering on before initKBOn	equ KBufOn+2	;1 if keyboard interrupts on before initVBLOn	equ KBOn+2	;1 if VBL interrupts on before initSaveMode	equ VBLOn+2	;original mouse modeSaveP	equ SaveMode+2	;original processor	statusProgID	equ SaveP+2	;program ID used with mem mgrFromGNE	equ ProgID+2	;flag used by GetOSEventAutoKeyLimit	equ FromGNE+2	; added 30 Jun 88 SEGktransRef	equ AutoKeyLimit+2	; added 1/22/89 Mensch (4 byte)kTransFlag	equ kTransRef+4	; added 1/23/89 Mensch (2 Byte)kTransTemp	equ kTransFlag+2	; added 4/19/89 Mensch (2 Byte);kTransBParamLoc	equ $5A	; battery ram parameter we use...*---------------------------------------------------------------* Window Manager Zero Page (used by Event Manager)*---------------------------------------------------------------WMZBase	equ 128FlgActive	equ WMZBaseFlgDeActive	equ FlgActive+2CurActive	equ FlgDeActive+2CurDeActive	equ CurActive+4CurDeKind	equ CurDeActive+4;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT EndCall0	IMPORT EndCall10	IMPORT EndCall14	IMPORT EndCall2	IMPORT EndCall4	IMPORT EndCall6	IMPORT ErrOut0	IMPORT ErrOut10	IMPORT ErrOut14	IMPORT ErrOut2	IMPORT ErrOut4	IMPORT ErrOut6	IMPORT GetVectorGlue	IMPORT IRQ_Heart	IMPORT MouseEquates	IMPORT SetVectorGlue	IMPORT SpecialNewHandle	IMPORT oEndCall0	IMPORT oErrOut0	IMPORT oErrOut14;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY Button	ENTRY DeQueue	ENTRY DeskAcc	ENTRY DoJournal	ENTRY DoWindows	ENTRY EMActive	ENTRY EMBootInit	ENTRY EMReset	ENTRY EMShutDown	ENTRY EMStartUp	ENTRY EMVersion	ENTRY EnQueue	ENTRY EventAvail	ENTRY FakeMouse	ENTRY FillRecord	ENTRY FlushBuf	ENTRY FlushEvents	ENTRY GetCaretTime	ENTRY GetDblTime	ENTRY GetGlobalLoc	ENTRY GetMouse	ENTRY GetNextEvent	ENTRY GetOSEvent	ENTRY KeyBoard	ENTRY LockQ	ENTRY Mouse	ENTRY Mouse3	ENTRY MouseTask	ENTRY OSEventAvail	ENTRY PostEvent	ENTRY SetEventMask	ENTRY SetModBits	ENTRY SetSwitch	ENTRY StillDown	ENTRY TickCount	ENTRY UnLockQ	ENTRY WaitMouseUp	Entry GetKeyTranslation	Entry SetKeyTranslation****************************************************************** CALL TABLE*****************************************************************	EXPORT EMCallTableEMCallTable	PROC	import SetAutoKeyLimit	DC.L (TheEnd-EMCallTable)/4 ;num calls + 1	DC.L EMBootInit-1	DC.L EMStartUp-1	DC.L EMShutDown-1	DC.L EMVersion-1	DC.L EMReset-1	DC.L EMActive-1	DC.L oEndCall0-1	DC.L oEndCall0-1	DC.L DoWindows-1	DC.L GetNextEvent-1	DC.L EventAvail-1	DC.L GetMouse-1	DC.L Button-1	DC.L StillDown-1	DC.L WaitMouseUp-1	DC.L TickCount-1	DC.L GetDblTime-1	DC.L GetCaretTime-1	DC.L SetSwitch-1	DC.L PostEvent-1	DC.L FlushEvents-1	DC.L GetOSEvent-1	DC.L OSEventAvail-1	DC.L SetEventMask-1	DC.L FakeMouse-1		; $1906	DC.L SetAutoKeyLimit-1	; $1A06	DC.L GetKeyTranslation-1	; 2/7/89 {$1B06}	DC.L SetKeyTranslation-1	; 2/7/89 {$1C06}TheEnd		; 	ENDP;                APPEND init****************************************************************** DATA DECLARATIONS*****************************************************************	EXPORT EMDataEMData	PROC*---------------------------------------------------------------* Tables*---------------------------------------------------------------	EXPORT BStatMaskBStatMask	DC.B %00000000,%10000000 ;button 0 mask	DC.B %00000000,%00010000 ;button 1 mask	EXPORT MaskTableMaskTable	DC.B %00000001,%00000000	DC.B %00000010,%00000000	DC.B %00000100,%00000000	DC.B %00001000,%00000000	DC.B %00010000,%00000000	DC.B %00100000,%00000000	DC.B %01000000,%00000000	DC.B %10000000,%00000000	DC.B %00000000,%00000001	DC.B %00000000,%00000010	DC.B %00000000,%00000100	DC.B %00000000,%00001000	DC.B %00000000,%00010000	DC.B %00000000,%00100000	DC.B %00000000,%01000000	DC.B %00000000,%10000000	EXPORT ModBitTableModBitTable	DC.B %00000000,%00000010 ;ShiftKey bit	DC.B %00000000,%00010000 ;ControlKey bit	DC.B %00000000,%00000100 ;CapsLock bit	DC.B %00000000,%00000000	DC.B %00000000,%00100000 ;KeyPad bit	DC.B %00000000,%00000000	DC.B %00000000,%00001000 ;OptionKey bit	DC.B %00000000,%00000001 ;AppleKey bit	EXPORT ClickTableClickTable	DC.L 50	DC.L 40	DC.L 30	DC.L 20	DC.L 10	EXPORT FlashTableFlashTable	DC.L 0	;no flash	DC.L 60	DC.L 30	DC.L 15	DC.L 10	EXPORT FDBDataFDBData	DC.B $10	;data byte used for	FDB tool call	ENDP****************************************************************** EMBootInit*****************************************************************	EXPORT EMBootInitEMBootInit	PROC	jmp oEndCall0	ENDP****************************************************************** EMStartUp** Modified 1/22/89 Mensch* Calls the DoLoadKTrans routine at startup to load the current ktrans table* and store a pointer to it in direct page.** See beginning of file. --DAL*****************************************************************	EXPORT EMStartUpEMStartUp	PROC	Import DoLoadKTrans	import UseCoolMousePos	cmp #0	;already initialized?	beq Doit	;no	ldx #InitErr	;yes - so return error	jmp oErrOut14Doit	phd	lda 21,s	;get zero page address	tcd	ldx #$FELoop	stz <EMZBase,x	;clear zero page	dex	dex	bpl Loop	lda #0	ldx #10	;12 bytes to clearLoop2	sta >EvMgrData,x	;clear permanent data area	dex	dex	bpl Loop2	lda 9,s	;get program ID	sta <ProgID	lda 19,s	;get queue size (# event records)	bne CheckSize	lda #DefaultQ	;default queue sizeCheckSize	cmp #MaxQ+1	bcc OK	ldx #SizeErr	;queue size too big	jmp ErrOut14OK	inc a	;first element of Q	never used	sta <QSize	asl a	;multiply queue size by 18 to get	asl a	;size in bytes	asl a	;QSize * 8	clc	adc <QSize	;QSize * 9	asl a	;QSize * 18	ldx <ProgID	ldy #$0004	; page aligned, unpurgeable	jsr SpecialNewHandle	bcc GotMem	ldx #MemErr	jmp ErrOut14GotMem	stx <QHandle	sty <QHandle+2	jsr LockQ	;lock Q and dereference handle	ldx <QSize	ldy #EvtOffset	;offset to event code in elementQLoop	lda #$FFFF	sta [<QPtr],y	;mark all Q elements as free	tya	clc	adc #EvtQSize	tay	dex	bne QLoop	lda #$EEEE	ldy #EvtOffset	sta [<QPtr],y	;mark first Q element as used	jsr UnLockQ	;unlock queue	lda #$FFFF	;init system event mask to post	sta <SysEventMask	;all events	php	php	pla	;save original processor status	sta <SaveP	sei	;turn off interrrupts	pha	;get status of hardware interrupts	_GetIRQEnable	pla	xba	rol a	rol <KBOn	;set flag if keyboard interrupts on	rol a	rol <VBLOn	;set flag if VBL interrupts on;		;save original interrupt vectors	pha	pha	PushWord #$0D	mouse	jsl GetVectorGlue	pla	sta <MouseAdrs	pla	sta <MouseAdrs+2	pha	pha	PushWord #$0F	;keyboard	jsl GetVectorGlue	pla	sta <KBAdrs	pla	sta <KBAdrs+2	pha	pha	PushWord #$12	;desk accessory	jsl GetVectorGlue	pla	sta <DAAdrs	pla	sta <DAAdrs+2	pha	pha	PushWord #$13	;flush buffer	jsl GetVectorGlue	pla	sta <FBAdrs	pla	sta <FBAdrs+2	pha	pha	PushWord #$0C	;VBL	jsl GetVectorGlue	pla	sta <VBLAdrs	pla	sta <VBLAdrs+2;		;install interrupt handlers	PushWord #$0D	PushPtr Mouse	;mouse	jsl SetVectorGlue	PushWord #$0F	PushPtr KeyBoard	;keyboard	jsl SetVectorGlue	PushWord #$12	PushPtr DeskAcc	;desk accessory	jsl SetVectorGlue	PushWord #$13	PushPtr FlushBuf	;flush buffer	jsl SetVectorGlue	PushWord #$0C	PushPtr IRQ_Heart	;VBL	jsl SetVectorGlue	pha	;result	PushWord #KeyBufParam ;get status of keyboard buffering	_ReadBParam	pla	sta <KBufOn	bne DoInts	;keyboard buffering	is on	PushWord #1	;# of data bytes	PushPtr FDBData	;push address of data byte	PushWord #4	;mode cmd	_SendInfo	;(_FDBCmd)	;enable keyboard bufferingDoInts	PushWord #2	;enable VBL interrupts	_IntSource	PushWord #0	;enable keyboard interrupts	_IntSource	PushWord #10	;enable data reg interrupts	_IntSource	lda >MouseSlot-1	;has SetMouse been called?	bmi NoMode	;no;	xba	;get slot in lo byte;	and #$FF	;mask off hi byte;	tax;	lda >MouseMode,x	;get current mode	lda >MseMode	;get current mode	and #$F	;mask off all but bits 0-3	sta <SaveModeNoMode	PushWord #0	;find mouse	_InitMouse	bcs SetClamps	;branch if no mouse	inc <GotMouse	;set mouse flag;	lda >MouseSlot	;check slot mouse is in;	and #$FF	;mask off hi byte;	cmp #4	;in slot 4?;	bne DoExt	;no - so external card;	LONGA off;	LONGI off;	sep #%00110000	;go into 8-bit mode;	lda >CardType;	LONGA on;	LONGI on;	rep #%00110000	;go back to 16-bit mode;	and #$10	;check bit 4;	bne DoExt	;it's set so external card;		;it's clear so internal FDB mouse	PushWord #7	;interrupt on movement and button	_SetMouse	;turn on mouse	bra SetClamps;DoExt	PushWord #1	;transparent mode;	_SetMouse	;turn on mouse;	lda #1;	sta <ExtMouse	;set external mouse	flag;	sta >TaskHead+4	;set up task counter;	lda #TaskSig;	sta >TaskHead+6	;set up signature word;	lda #MouseTask;	pha;	xba	;set up JMP to MouseTask;	and #$FF00;	ora #$005C;	sta >TaskHead+8;	pla;	and #$FF00;	ora #^MouseTask;	xba;	sta >TaskHead+10;	PushPtr TaskHead;	_SetHeartBeat	;install mouse task	in heartbeat queueSetClamps	lda 17,s	;X min	pha	sta >EMXPos	;init X position in	case no mouse	lda 17,s	;X max	sec	sbc #1	pha	lda 17,s	;Y min	pha	sta >EMYPos	;init Y position in	case no mouse	lda 17,s	;Y max	sec	sbc #1	pha	_ClampMouse	;set mouse (relative device) clamps	lda 17,s	;X min	pha	lda 17,s	;X max	sec	sbc #1	pha	lda 17,s	;Y min	pha	lda 17,s	;Y max	sec	sbc #1	pha	_SetAbsClamp	;set absolute device clamps	_HomeMouse	;position mouse at min clamps	bcs Done	;branch if no mouse	pha	pha	pha	_readMouse2	;set up initial values	pla	sta >EMBStat	pla	sta >EMYPos	pla	sta >EMXPosDone	lda >EMXPos	pha	lda >EMYPos	pha	jsl CUpdate	;init cursor to min	clamps	lda 21,s	;get zero page address	PushWord #0	PushWord #EMTSNum	PushWord #0	pha	_SetWAP	;set work area pointer	jsl UseCoolMousePos	;added 24-Feb-91 DAL	jsr DoLoadKTrans	; added 1/22/89 and 2/13/89!	cli	;enable interrupts	jmp EndCall14	ENDP****************************************************************** EMShutDown*****************************************************************	EXPORT EMShutDownEMShutDown	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;return error if EM	not active	jmp ErrOut0Doit	sei	;turn off  interrupts	pea TaskHead>>16	pea TaskHead**$FFFF	_DelHeartBeat	;remove mouse task from heartbeat Q	lda <KBufOn	;was keyboard buffering on before init?	bne Cont	;yes - so don't turn off	PushWord #1	;# of data bytes	PushPtr FDBData	;push address of data byte	PushWord #5	;mode cmd	_SendInfo	; (_FDBCmd)	;disable keyboard bufferingCont	lda <VBLOn	;were VBL interrupts on before init?	bne Cont1	;yes - so don't turn off	PushWord #3	;disable VBL interrupts	_IntSourceCont1	lda <KBOn	;were keyboard interrupts on	bne Cont2	;yes - so don't turn off	PushWord #1	;disable keyboard interrupts	_IntSourceCont2	lda <GotMouse	;is mouse present?	beq Cont3	;no	lda <SaveMode	;yes - so set mouse	mode back to	pha	;original value	_SetMouse;		;restore original interrupt vectorsCont3	PushWord #$0D	PushLong <MouseAdrs	;mouse	jsl SetVectorGlue	PushWord #$0F	PushLong <KBAdrs	;keyboard	jsl SetVectorGlue	PushWord #$12	PushLong <DAAdrs	;desk accessory	jsl SetVectorGlue	PushWord #$13	PushLong <FBAdrs	;flush buffer	jsl SetVectorGlue	PushWord #$0C	PushLong <VBLAdrs	;VBL	jsl SetVectorGlue	lda <QHandle+2	;release queue space	pha	lda <QHandle	pha	_DisposeHandle; dump the keytrans table that we loaded to start with ...	pha	; room for result	lda #kTransBParamLoc	pha	_ReadBParam	; get our parameter	pla	beq DDKTDone	; if zero, then bag it!	and #$00FF	ora #$0600	; add event mgr ID	tax	; save it in <X> for a seconf...	pea $8021	; ktrans resource type	pea $0FFF	; resource ID; create the low byte of the ID here!	phx	; event manager resource #1	_ReleaseRomResource	; now call releaseROMResourceDDKTDone	PushWord #0	PushWord #EMTSNum	PushWord #0	PushWord #0	_SetWAP	;clear work area pointer	lda <SaveP	pha	plp	plp	;restore original processor status	jmp EndCall0	ENDP****************************************************************** EMVersion*****************************************************************	EXPORT EMVersionEMVersion	PROC	lda #EMVerNum	sta 7,s	jmp oEndCall0	ENDP****************************************************************** EMReset*****************************************************************	EXPORT EMResetEMReset	PROC	cmp #0	;is EM active?	beq Done	;no	ldx #ResetErr	;yes - so return error	jmp oErrOut0Done	jmp oEndCall0	ENDP****************************************************************** EMActive*****************************************************************	EXPORT EMActiveEMActive	PROC	sta 7,s	jmp oEndCall0	ENDP;                APPEND tbem****************************************************************** DoWindows*****************************************************************	EXPORT DoWindowsDoWindows	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut0Doit	sta 9,s	;return Event Mgr's zero page reg	lda #1	sta <WindowMgr	;set flag	jmp EndCall0	ENDP****************************************************************** GetNextEvent*****************************************************************	EXPORT GetNextEventGetNextEvent	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut6Doit	inc <RemoveEvent	EXPORT GNECommonGNECommon		;       	lda 9,s	;move event ptr onto zero page	sta <UserEvtPtr	lda 11,s	sta <UserEvtPtr+2	jsr GetNullEvent	;get a null event record	jsr CheckActivate	;check for activate	event	bne GotEvent	jsr CheckSwitch	;check for switch event	bne GotEvent	jsr CheckQueue	;check event queue	bne GotEvent	jsr CheckUpdate	;check for update event	bne GotEvent	lda >JournalFlag	;journaling on?	beq Done	;no	PushWord #0	;push address of TempEvent	clc	;so GetMouse will have a place to	tdc	;store its result	adc #TempEvent	pha	jsl xGetMouse	;read mouse so it will be journalled	bra RetFalse	;return a null eventGotEvent		lda <RemoveEvent	;EventAvail call?	beq RetTrue	;yes - so don't call Desk Mgr	PushWord #0	;push result	ldy #EvtSize-2	;push event on stackLoop	lda [<UserEvtPtr],y	pha	dey	dey	bpl Loop	_SystemEvent	;call Desk Mgr	pla	;did system grab event?	beq RetTrue	;noRetFalse	lda #False	;yes	bra DoneRetTrue	lda #TrueDone	sta 15,s	stz <RemoveEvent	jmp EndCall6*------------------------------------------------------------------------------GetNullEvent	lda #0	;mask out all events	jsr GetEvent	rts*-------------------------------------------------------------------------------CheckActivate	lda 15,s	;get event mask	and #BActivate	;activate event enabled?	beq ADone	;no - so return false	lda <FlgDeActive	;see if deactive event pending	bne GotDeActive	;got one	lda <FlgActive	;see if activate event pending	beq ADone	;none so return false	ldy #MsgOffset	lda <CurActive	;move window pointer into event msg	sta [<UserEvtPtr],y	iny	iny	lda <CurActive+2	sta [<UserEvtPtr],y	lda #1	sta <TempBits	;set activate flagGotActCommon	lda <CurDeActive	;get deactivated window	beq Q1	;branch if none	lda <CurActive	;get active window	beq Q1	;branch if none	ldy #KindOffset	lda [<CurActive],y	;get WindowKind	eor <CurDeKind	;did hi bit change?	bpl Q1	;no	lda <Tempbits	ora #2	;set change flag	sta <TempBitsQ1	ldy #ModsOffset	lda [<UserEvtPtr],y	;get modifiers field	ora <TempBits	;or in flag bits	sta [<UserEvtPtr],y	;put it back	lda <RemoveEvent	;EventAvail call?	beq ACont	;yes - so don't clear flags	lda <FlgDeActive	;deactivate event?	beq ClearActive	;no - so must be activate event	stz <FlgDeActive	;clear deactivate flag	bra AContClearActive	stz <FlgActive	;clear activate flagACont	lda #Activate	sta [<UserEvtPtr]	;event code	lda #TrueADone	rtsGotDeActive	stz <TempBits	;clear the activate	flag	ldy #MsgOffset	lda <CurDeActive	;move window pointer into event msg	sta [<UserEvtPtr],y	iny	iny	lda <CurDeActive+2	sta [<UserEvtPtr],y	bra GotActCommon*-------------------------------------------------------------------------------CheckSwitch	lda 15,s	;get event mask	and #BSwitch	;switch event enabled?	beq SDone	;no	lda <GotSwitchCall	;switch call received?	beq SDone	;no - so return false	lda 15,s	;get event mask	jsr UCont	;check for pending update events	bne SDone	;got one so return it	lda <RemoveEvent	;EventAvail call?	beq SCont	;yes - so don't clear flag	stz <GotSwitchCall	;clear switch flagSCont	lda #Switch	;no update events so return switch event	sta [<UserEvtPtr]	lda #TrueSDone	rts*-------------------------------------------------------------------------------CheckQueue	inc <FromGNE	lda 15,s	;get event mask	jsr GetEvent	stz <FromGNE	;clear flag	lda >JournalFlag	;journaling on?	beq QDone	;no	lda <UserEvtPtr	;move user's event pointer into	sta <JResultPtr	;journal result pointer	lda <UserEvtPtr+2	sta <JResultPtr+2	ldx #JcEvent	;journal code	jsr DoJournalQDone	lda [<UserEvtPtr]	;get event code - 0	if no event	rts*-------------------------------------------------------------------------------CheckUpdate	lda 15,s	;get event maskUCont	and #BUpdate	;update event enabled?	beq UDone	;no - so return false	lda <WindowMgr	;is Window Mgr initialized?	beq UDone	;no - so return false	PushWord #0	;push result	PushLong <UserEvtPtr ;push event ptr	_CheckUpdate	;call Window Mgr	pla	;get resultUDone	rts*------------------------------------------------------------------------------GetEvent	PushWord #0	;push result	pha	;push event mask	PushLong <UserEvtPtr ;push event ptr	lda <RemoveEvent	;EventAvail call?	beq Peek	;yes	jsl xGetOSEvent	bra GDonePeek	jsl xOSEventAvailGDone	pla	;pull result	rts*------------------------------------------------------------------------------xGetMouse	tdc	jsl GetMouse	rtlxGetOSEvent	tdc	jsl GetOSEvent	rtlxOSEventAvail	tdc	jsl OSEventAvail	rtl	Entry DoLoadKTransDoLoadKTrans; This should be called by our startup routine to load the keytrans table to start	stz <ktransRef	stz <ktransRef+2	stz <kTransFlag	pea $FFFF	; special setktrans flag	_SetKeyTranslationDLKTDone	rts	; and leave...	ENDP****************************************************************** EventAvail*****************************************************************	EXPORT EventAvailEventAvail	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut6Doit	jmp GNECommon	ENDP****************************************************************** GetMouse*****************************************************************	EXPORT GetMouseGetMouse	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut4Doit	php	sei	lda 10,s	;put user's pointer on zero page	sta <TempPtr	lda 12,s	sta <TempPtr+2	ldy #0	jsr GetGlobalLoc	;get mouse loc in global coordinates	lda >JournalFlag	;journaling on?	beq Cont	;no	lda <TempPtr	;move user's result pointer into	sta <JResultPtr	;journal result pointer	lda <TempPtr+2	sta <JResultPtr+2	ldx #JcGetMouse	;journal code	jsr DoJournalCont	PushLong <TempPtr	;push user's result pointer on stack	_GlobalToLocal	;call QuickDraw to map to local coords	plp	jmp EndCall4	ENDP****************************************************************** Button*****************************************************************	EXPORT ButtonButton	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut2Doit	lda 9,s	;get button #	cmp #2	bcc Cont	ldx #BtnErr	;illegal button #	jmp ErrOut2Cont	asl a	tax	lda >EMBStat	;get status byte	and >BStatMask,x	;mask off correct button bit	beq Return	;button up so return false	lda #True	;button down so return trueReturn	sta 11,s	;return result	lda >JournalFlag	;journaling on?	beq Done	;no	stz <JResultPtr+2	;set up pointer to result for journaling	clc	tsc	adc #11	sta <JResultPtr	ldx #JcButton	;journal code	jsr DoJournalDone	jmp EndCall2	ENDP****************************************************************** StillDown*****************************************************************	EXPORT StillDownStillDown	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut2Doit	lda 9,s	;get button #	cmp #2	bcc Cont	ldx #BtnErr	;illegal button #	jmp ErrOut2Cont	PushWord #0	;push result	pha	;push button #	jsl xButton	;is button down?	pla	;get result	beq Return	;button is up so return false	inc <CheckButton	;set flag for EventAvail	lda 9,s	;get button #	sta <WhichButton	PushWord #0	;push result	PushWord #7	;push mask for button events	PushWord #0	;push address of TempEvent (4 bytes)	tdc	clc	adc #TempEvent	pha	jsl xEventAvail	;check for button events	stz <CheckButton	;clear flag	pla	;get result	bne GotEvent	lda #True	;no button events so return true	bra ReturnGotEvent	lda #False	;got event so return falseReturn	sta 11,s	jmp EndCall2xButton	tdc	jsl Button	rtlxEventAvail	tdc	jsl EventAvail	rtl	ENDP****************************************************************** WaitMouseUp*****************************************************************	EXPORT WaitMouseUpWaitMouseUp	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut2Doit	lda 9,s	;get button #	cmp #2	bcc Cont	ldx #BtnErr	;illegal button #	jmp ErrOut2Cont	PushWord #0	;push result	pha	jsl xStillDown	;is button still down?	pla	;get result	bne Return	;button is still down so return true	inc <CheckButton	;set flag for GetNextEvent	lda 9,s	;get button #	sta <WhichButton	PushWord #0	;push result	PushWord #4	;push mask for button up events only	PushWord #0	;push address of TempEvent	tdc	clc	adc #TempEvent	pha	jsl xGetNextEvent	;remove button up event	stz <CheckButton	;clear flag	pla	;get result	lda #False	;return falseReturn	sta 11,s	jmp EndCall2xStillDown	tdc	jsl StillDown	rtlxGetNextEvent	tdc	jsl GetNextEvent	rtl	ENDP****************************************************************** TickCount** Change History** 29 Jun 88	Steven Glass** Two things were wrong here.  First the TickCnt was being * accessed with interrupts active and second, if journaling* was active, the journaling code was called with the* wrong direct page register.** To fix this we always switch D-reg and use EndCall0 to * finish up.  We also turn interrupts off.*****************************************************************	EXPORT TickCountTickCount	PROC	DefineStackorigP	byteorigD	wordRTL1	block 3RTL2	block 3Result	long	cmp #0	bne Doit	ldx #ActiveErr	;EM not active	jmp oErrOut0Doit	phd	; save D	tcd	php	; save interrupt state	sei	lda >TickCnt	sta Result,s	lda >TickCnt+2	sta Result+2,s	plp	; restore interrupts now	lda >JournalFlag	;journaling on?	beq Done	;no	stz <JResultPtr+2	;set up pointer to result for journaling	clc	tsc	adc #7	sta <JResultPtr	ldx #JcTickCount	;journal code	jsr DoJournalDone	jmp EndCall0	; get out and restore D	ENDP****************************************************************** GetDblTime*****************************************************************	EXPORT GetDblTimeGetDblTime	PROC	cmp #0	bne Doit	ldx #ActiveErr	;EM not active	jmp oErrOut0Doit	PushWord #0	;result	PushWord #ClickParam ;double click param reference	_ReadBParam	;read battery ram	pla	;double click rate (0-4)	asl a	asl a	tax	lda >ClickTable,x	;translate into ticks	sta 7,s	inx	inx	lda >ClickTable,x	sta 9,s	jmp oEndCall0	ENDP****************************************************************** GetCaretTime*****************************************************************	EXPORT GetCaretTimeGetCaretTime	PROC	cmp #0	bne Doit	ldx #ActiveErr	;EM not active	jmp oErrOut0Doit	PushWord #0	;result	PushWord #FlashParam ;flash rate param reference	_ReadBParam	;read battery ram	pla	;flash rate (0-4)	asl a	asl a	tax	lda >FlashTable,x	;translate into ticks	sta 7,s	inx	inx	lda >FlashTable,x	sta 9,s	jmp oEndCall0	ENDP****************************************************************** SetSwitch*****************************************************************	EXPORT SetSwitchSetSwitch	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut0Doit	lda #1	sta <GotSwitchCall	jmp EndCall0	ENDP;                APPEND osem****************************************************************** PostEvent** Change History** 30 Jun 88	Steven Glass & Cheryl Ewy** Change made so that auto key events are only * posted if the number of elements in the queue is less than or* equal to a specified limit.  The limit is set to 0 by * EMStartup and an application can change the limit by calling the* new tool call SetAutoKeyLimit.*****************************************************************	EXPORT PostEventPostEvent	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut6Doit	lda 13,s	;get event code	cmp #16	bcc OK	ldx #CodeErr	;illegal event code	jmp ErrOut6	;return the errorOK	php	sei	asl a	tax	lda >MaskTable,x	;get bit mask for code	and <SysEventMask	;is this event enabled?	bne CheckAutoKey	;yes - so check if auto-key eventErrRet	lda #1	;no - so return an error	sta 16,s	plp	jmp EndCall6CheckAutoKey	lda 14,s	;get event code	cmp #AutoKey	;auto-key event?	bne GetFreeOne	;no - so post it	lda <QHead	;is the queue empty?	beq GetFreeOne	;yes - so post it!	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	jsr LockQ	; lock and deref Q	ldx #0	; count elements in queue	ldy <QHead	; start with queue headLoop	inx	; bump counter	lda [<QPtr],y	; get link to next element in Q	tay	; repeat till	bne Loop	; none	cpx <AutoKeyLimit	; check limit	bcs ErrRet	; too much, return error	bra QLocked	; we have room, so post itGetFreeOne	jsr LockQQLocked	ldy #EvtOffset	;get offset to event code in element	ldx <QSize	;max # of queue elements@Loop	lda [<QPtr],y	;get event code of queue element	cmp #$FFFF	;is this element free?	beq GotFreeOne	;yes	clc	;no - so go on to next element	tya	adc #EvtQSize	tay	dex	;have we checked all queue elements?	bne @Loop	;no;		;yes - so remove first element in Q	ldy <QHead	lda [<QPtr],y	;move link pointer from first queue	sta <QHead	;element into QHead	iny	inyGotFreeOne	clc	;construct pointer to event record part	tya	;of free element	adc <QPtr	sta <TempPtr	lda #0	adc <QPtr+2	sta <TempPtr+2	dey	dey	sty <TempLink	;save link to queue	elementSetFields	lda 14,s	;get event code	sta [<TempPtr]	;store it in the event record	ldy #MsgOffset	lda 10,s	;get the event msg	sta [<TempPtr],y	;store it in the event record	iny	iny	lda 12,s	sta [<TempPtr],y	jsr FillRecord	;fill in rest of record	jsr EnQueue	;add record to queue	jsr UnLockQ	plp	;restore interrupt state	lda #0	sta 15,s	;zero result code	jmp EndCall6	ENDP****************************************************************** FlushEvents*****************************************************************	EXPORT FlushEventsFlushEvents	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut4Doit	php	;save interrupt status	sei	;turn off interrupts	jsr LockQ	lda <QHead	;get link to first queue element	sta <TempLink	tay	beq Done	;if 0 then queue is	emptyLoop	iny	;get offset to event part of Q element	iny	lda [<QPtr],y	;get event code	cmp #16	bcc OK	PushWord #QError	;illegal event code	- Q trashed	PushWord #0	PushWord #0	_SysFailMgr	;dieOK	asl a	tax	lda >MaskTable,x	;get bit mask for event code	tax	;save mask in X	and 10,s	;is it in the stop mask?	bne Stop	;yes - so stop	txa	;get event mask back	and 12,s	;is it in the event	mask?	beq Cont	;no	lda #$FFFF	sta [<QPtr],y	;set event code to unused	jsr DeQueue	;remove element from queueCont	ldy <TempLink	lda [<QPtr],y	;follow link to next Q element	sta <TempLink	tay	bne Loop	;continue if not end of queue	bra Done	;end of queue so return 0Stop	lda [<QPtr],y	;get event code backDone	sta 14,s	;store result	jsr UnLockQ	plp	;restore interrupt status	jmp EndCall4	ENDP****************************************************************** GetOSEvent*****************************************************************	EXPORT GetOSEventGetOSEvent	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut6Doit	inc <OSRemoveEvent	EXPORT GOSECommonGOSECommon		;       	php	;save interrupt status	sei	;turn off interrupts	jsr LockQ	lda 14,s	;get mask	beq RetNull	;branch if mask is 0	lda <QHead	;move link to first	queue element	sta <TempLink	;into TempLink	tay	beq RetNull	;if 0 then queue is	emptyGetEvent	iny	;offset to event code	iny	lda [<QPtr],y	;get event code of queue element	cmp #16	bcc OK	PushWord #QError	;illegal event code	- Q trashed	PushWord #0	PushWord #0	_SysFailMgr	;dieOK	phy	;preserve registers.	pha	;	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	pla	ply	asl a	;multiply by 2	tax	lda >MaskTable,x	;get mask corresponding to event code	and 14,s	;is this event enabled?	beq Cont	;no - so continue looking	lda <CheckButton	;is button number important?	beq GotEvent	;no - so we have an	OK event	lda [<QPtr],y	;get event code again	cmp #3	;is it a button up/down event?	bcs GotEvent	;no - so we have an	OK event	clc	tya	adc #MsgOffset	tay	lda [<QPtr],y	;get message field from event record	cmp <WhichButton	;is it the correct button?	beq GotEvent	;yes - so we have an OK eventCont	ldy <TempLink	lda [<QPtr],y	;follow link to next queue element	sta <TempLink	tay	bne GetEvent	;branch if not end of queue;		;return null eventRetNull	lda <FromGNE	;called from GetNextEvent?	bne RetFalse	;yes - so already have null event	lda 10,s	;move user's event record pointer	sta <TempPtr	;onto zero page	lda 12,s	sta <TempPtr+2	lda #0	sta [<TempPtr]	;null event code	ldy #MsgOffset	sta [<TempPtr],y	;zero out event msg	iny	iny	sta [<TempPtr],y	jsr FillRecord	;fill in rest of event recordRetFalse	lda #False	bra Done	;return falseGotEvent	lda 10,s	;move user's event record pointer onto	sta <UserEvtPtr	;zero page	lda 12,s	sta <UserEvtPtr+2	clc	lda <TempLink	;create pointer to event part of	adc #EvtOffset	;queue element	adc <QPtr	sta <TempPtr	lda #0	adc <QPtr+2	sta <TempPtr+2	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	ldy #EvtSize-2Loop	lda [<TempPtr],y	;move event into user's event parameter	sta [<UserEvtPtr],y	dey	dey	bpl Loop	lda <OSRemoveEvent	;OSEventAvail call?	beq RetTrue	;yes - so don't remove event	lda #$FFFF	;no - so remove event from queue	ldy <TempLink	iny	iny	sta [<QPtr],y	;set event code to unused	jsr DeQueue	;remove element from queueRetTrue	lda #TrueDone	sta 16,s	;return result	stz <OSRemoveEvent	jsr UnLockQ	plp	;restore interrupt status	jmp EndCall6	ENDP****************************************************************** OSEventAvail*****************************************************************	EXPORT OSEventAvailOSEventAvail	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut6Doit	jmp GOSECommon	ENDP****************************************************************** SetEventMask*****************************************************************	EXPORT SetEventMaskSetEventMask	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut2Doit	lda 9,s	sta <SysEventMask	jmp EndCall2	ENDP****************************************************************** FakeMouse*****************************************************************	EXPORT FakeMouseFakeMouse	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;EM not active	jmp ErrOut10Doit	lda 9,s	;get button status	sta >EMBStat	lda 11,s	;get Y position	sta >EMYPos	lda 13,s	;get X position	sta >EMXPos;	lda <ExtMouse	;external mouse?;	bne DoExt	;yes;	sep #$30	;go into 8-bit mode;	LONGA off	;stuff new XY into mouse screenholes;	LONGI off;	lda >MouseSlot	;get slot # of mouse;	bmi NoMouse	;branch if no mouse;	tax;	lda >EMXPos	;get lo X;	sta >MouXL,x;	lda >EMXPos+1	;get hi X;	sta >MouXH,x;	lda >EMYPos	;get lo Y;	sta >MouYL,x;	lda >EMYPos+1	;get hi Y;	sta >MouYH,x;NoMouse	rep #$30	;go back to 16-bit mode;	LONGA on;	LONGI on;	bra Cont;DoExt	lda >EMXPos;	pha;	lda >EMYPos;	pha;	_PosMouse	;position mouse at new XY	sep #$30	;go into 8-bit mode	LONGA OFF	;stuff new XY into mouse absolute position	LONGI OFF	lda >EMXPos	;get lo X	sta >LowAbsx	lda >EMXPos+1	;get hi X	sta >HighAbsx	lda >EMYPos	;get lo Y	sta >LowAbsy	lda >EMYPos+1	;get hi y	sta >HighAbsy	rep #$30	;go back into 16-bit mode	LONGA ON	LONGI ONCont	lda 15,s	;get mod keys latch	tax	lda 17,s	;get fake servemouse result	jsl Kludge	;force a return addr onto the stack so;		;mouse interrupt routine will RTL here	rep #$30	;get back into 16-bit mode since mouse	jmp EndCall10	;interrupt routine exits in 8-bit modeKludge	pha	;push fake servemouse result	phx	;push mod keys latch	jmp Mouse3	;jmp into mouse interrupt routine	ENDP;                APPEND misc****************************************************************** EnQueue*****************************************************************	EXPORT EnQueueEnQueue	PROC	;interrupts must be	off	lda #0	;zero out link field of new element	ldy <TempLink	sta [<QPtr],y	lda <QHead	;is queue empty?	bne DoInsert	;no - so insert element	lda <TempLink	;yes - so set QHead	and QTail	sta <QHead	;to the new element	sta <QTail	bra DoneDoInsert	lda <TempLink	;update current last Q element	ldy <QTail	;to link to new last Q element	sta [<QPtr],y	sta <QTail	;set QTail to the new lastDone	rts	;queue element	ENDP****************************************************************** DeQueue*****************************************************************	EXPORT DeQueueDeQueue	PROC	;interrupts must be	off	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	lda <QHead	cmp <TempLink	;are we deleting the first element?	beq DeleteFirst	;yesLoop	tay	lda [<QPtr],y	;does this element link to the one we	cmp <TempLink	;want to delete?	beq DeleteIt	;yes - so delete it	lda [<QPtr],y	;no - so follow link to next element	bne Loop	;have we reached the end of the queue?Done	rtsDeleteFirst	ldy <TempLink	lda [<QPtr],y	;link QHead to element following the	sta <QHead	;one we are deleting	lda <TempLink	cmp <QTail	;was it the only element?	bne Done	;no	lda #0	;yes - so set QTail	to 0	sta <QTail	bra DoneDeleteIt	tyx	;save link to preceeding element	ldy <TempLink	lda [<QPtr],y	;unlink element from chain	txy	sta [<QPtr],y	lda <TempLink	cmp <QTail	;was it the last element?	bne Done	;no	stx <QTail	;yes - so set QTail	to element	bra Done	;predeeding the one	we deleted	ENDP****************************************************************** LockQ*****************************************************************	EXPORT LockQLockQ	PROC	lda <QHandle	ora <QHandle+2	;is Q handle 0?	bne OK	;no	PushWord #HError	;yes - so give fatal error	PushWord #0	PushWord #0	_SysFailMgrOK	ldy #4	lda [<QHandle],y	ora #$8000	;set locked bit in attribute word	sta [<QHandle],y	ldy #2	lda [<QHandle]	;dereference handle	sta <QPtr	lda [<QHandle],y	sta <QPtr+2	rts	ENDP****************************************************************** UnLockQ*****************************************************************	EXPORT UnLockQUnLockQ	PROC	lda <QHandle	ora <QHandle+2	;is Q handle 0?	bne OK	;no	PushWord #HError	;yes - so give fatal error	PushWord #0	PushWord #0	_SysFailMgrOK	ldy #4	lda [<QHandle],y	and #$7FFF	;clear locked bit in attribute word	sta [<QHandle],y	rts	ENDP****************************************************************** FillRecord*****************************************************************	EXPORT FillRecordFillRecord	PROC	;PostEvent and GetOSEvent JSR here	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	lda >TickCnt	;get current system	ticks	ldy #WhenOffset	sta [<TempPtr],y	lda >TickCnt+2	iny	iny	sta [<TempPtr],y	ldy #WhereOffset	jsr GetGlobalLoc	;get mouse loc in global coords	lda [<TempPtr]	;get event code	beq NormalMods	;branch if null event	cmp #6	;is it a keyboard or mouse event?	bcc SpecialMods	;yes - so mods are in msg	LONGA off	LONGI offNormalMods	sep #%00110000	;go into 8 bit mode	lda >ModLatch	;get mod keys latch	and push as hi byte	pha	lda #0	;push 0 in lo byte	pha	LONGA on	LONGI on	rep #%00110000	;go back to 16 bitmode	jsr SetModBits	;set up modifiers word in Y	pla	;pull mod keys latch	tya	;xfer modifiers word into A	ldy #ModsOffset	sta [<TempPtr],y	;store in Modifiers	field of record	rtsSpecialMods	ldy #MsgOffset+2	lda [<TempPtr],y	;modifiers are in high word of msg	ldy #ModsOffset	sta [<TempPtr],y	;store in mod field	of record	lda #0	ldy #MsgOffset+2	sta [<TempPtr],y	;zero out hi word of msg in record	rts	ENDP****************************************************************** GetGlobalLoc*****************************************************************	EXPORT GetGlobalLocGetGlobalLoc	PROC	;GetMouse and FillRecord JSR here	lda >EMYPos	sta [<TempPtr],y	iny	iny	lda >EMXPos	sta [<TempPtr],y	rts	ENDP****************************************************************** SetModBits*****************************************************************	EXPORT SetModBitsSetModBits	PROC	;FillRecord, Keyboard and Mouse JSR here	ldy #0	ldx #0	lda >EMBStat	;get button status	and >BStatMask,x	;is button 0 up?	bne Button1	;no	tya	;yes - so set bit	ora #Btn0Bit	tayButton1	ldx #2	lda >EMBStat	;get button status back	and >BStatMask,x	;is button 1 up?	bne Keys	;no	tya	;yes - so set bit	ora #Btn1Bit	tayKeys	ldx #14	lda 3,s	;get mod keys latch	phaLoop	lda 1,s	;get mod keys latch	asl a	;shift bits out left	sta 1,s	;save it	bcc Cont	;if the bit was set, set proper	tya	;bit in Y	ora >ModBitTable,x	tayCont	dex	dex	bpl Loop	pla	rts	;return with modifier word in Y	ENDP****************************************************************** DoJournal*****************************************************************	EXPORT DoJournalDoJournal	PROC	;TickCount, Button,	GetMouse, and	lda >JournalFlag	;journaling on?	beq Done	;no	pha	;push journal flag	phx	;push journal code	PushLong <JResultPtr ;push result pointer	jsl JournalPtr	;jump to journaling	codeDone	rts	ENDP;                APPEND ih****************************************************************** Keyboard Interrupt Handler** 1/23/89 Mensch* Added keyboard translation tables to this routine. My but this stuff* is pretty confused. Since it is so confused, I would like to present * you with the following:** "How does GS keyboard remapping work?"*           a play in 1 act*              By Mensch** Players:*   KTransRef - a handle/pointer to the current keyboard translation*               table*   KTransFlag - used by the "DeadKey" skimmer*   Steve - Boss of our hero*   Hero - The guy writing and explaining this.*   Mimi - One with international scope.**Scene 1* Steve and Mimi are in a meeting together.* Mimi 	"Steve, all the europeans hate the GS, they say*	that they can't type"* Steve	"Tough"* Mimi	"Please, help them to compute..." (touching smile)* Steve	"Ok, I will put that lazy hero on the job"**Scene 2* Steve and Hero are busy talking about something else when* Steve	"Oh, by the way, why don't you implement keyboard*	remapping, just like the mac's got... Mimi wanted*	us to do it for europe"* Hero	"OK, I will do it. I will modify getNextEvent"* Steve	"Don't be a putz, do it in the keyboard interupt*	handler code! God do I have to think of everything?"	**Scene 3* Hero comes back with some code and a proposal after some time and * explains to Steve how the new keymapping will work.* Steve	"Ok, run by me exactly how this ktrans stuff is *	going to work at the highest level"* Hero	"Well, it goes something like this: When an*	EMStartup call is made, we call getROMResource*	which will give us a handle to the keytrans table*	we then store it in the kTransRef and we store*	a zero in kTransFlag. If no table exists (Not likely)*	we store a zero in kTransRef. If a Disk based*	resource exists, we load it in. Notice that the*	handle is not locked, so it must be derefed every time*	we use it!"* Steve	"Hmmm ok, sounds good. I suppose you release the resource*	when you are done with it?"* Hero	{asside to the audience}'This guy must think I am*	completely stupid!'*	{to Steve}"Certainly, I dispose of it at EMShutdown time"* Steve	"Fine, now please tell me the details of this process,*	and after you are done telling me, could you document it *	in the code?"* Hero	"Ok, well the ktrans table is a variable sized data object*	that can be as small as 258 bytes, or as large as 768*	bytes. The first 256 bytes always contain single byte*	values that represent the character substitution array.*	when a key is pressed, the keyboard routine will use*	the ascii code of that key (notice also that if the *	option key is pressed down, I add 128 to the value) as*	an offset into the single byte substitution array. The resulting*	value is the key code we are to return to the program.* Steve	"OK I can see how that works, now lets say that you have a*	'dead' key, you know one of those two key sequences that*	generate a single ASCII character?"* Hero	"Well, as you can see, the first thing that I do is test*	to be sure the option key was really pressed. If it was*	I then set the current key as the dead key in the kTransFlag*	and test to see if the key is a qualifying dead key if so I*	return with carry set so that the event does not get posted.*	If not, I simply return with the carry clear and the key gets*	posted"** {Hero adjusts his chair, and starts looking a little frazeled}* Hero	"If a key is pressed after a "dead" key has been stored,*	I again find the dead key in the table and get its offset.*	once I have the proper offset I look thru the table to find*	the current key in that deadkey's modifier table. If I*	find it, I simply change the keydata to reflect the generated*	ascii code for the dead key combo. If I do not find*	the current key I post an event for the old dead key, and *	I return to the caller so it can post the current key."* Steve	"Wow, its that easy???"* Hero	"Sure is!"* {Curtain}*---------------- End of Play --------------------* Authors Notes:* Directors:* Please include the following description in the playbill for this program so* the patrons will have an easier time following the show!** kTransData structure:*  Sub_Array:Packed array[0..255] of char;*  Dead_KeyArray:Packed array[0..xx] of DeadKeyStruct; (must end in a NIL word)*  ModTables:Packed array[0..xx,0..yy] of ModifierWord; (Must end in NIL word)*  end;** DeadKeyStructure:*   Byte - keycode from Sub_Array;*   Byte - Offset/2 from end of Sub_Array to proper ModTable for this keycode** ModifierWord:*   Byte - keycode from Sub_Array;*   Byte - keycode for this deadKeyCombo;** NOTE: xx is the number of dead keys; yy is the number of keys each dead key* modifies.*****************************************************************	EXPORT KeyboardKeyboard	PROC	LONGA off	LONGI off	lda #0	pha	;store 0 as hi byte	of keypress	lda >KeyLatch	;get keypress	and #$7F	;clear hi bit	pha	;store in lo byte	lda >ModLatch	pha	;push mod keys latch	lda #0	pha	;push 0 as lo byte of mod keys latch	sta >KbdStrobe	;clear keyboard strobe	LONGA on	LONGI on	rep #$30	;go into 16 bit mode	jsr SetModBits	;set up modifiers word in Y	pla	;pull mod keys latch	plx	;pull keypress	PushWord #0	;push result	and #RepeatBit	;was repeat bit in mod latch set?	bne Repeat	;no - so push code for KeyDown event	PushWord #KeyDown	bra ContRepeat	PushWord #AutoKey	;yes - so push code	for AutoKey eventCont	phy	;push modifiers - hi word of message	phx	;push keypress - lo	word of message	jsr DoKTrans	; remap the key as needed	bcs BadKey	; if carry set, don't post the key, pull it off and end	_PostEvent	pla	;pull resultcont0010	sep #$30	;go back to 8 bit mode	LONGA off	LONGI off	clc	rtl	LongA On	LongI OnBadKey	pla	; discard the data we just pushed on the stack...	pla	pla	pla	bra cont0010*-------------------------------------------------------------------------------; This routine will modify the keycode and modifiers on the stack to support other; keyboard mapping schemes. 1/22/89;DoKTrans; test to see if we have a handle installed.temp	equ 1saveDPageRTS	equ temp+4KeyData	equ saveDPageRTS+4keyMods	equ keyData+2theWAPT	equ $E103C8	; wapt table reference	phd	; save the direct page	lda >theWapt+2	; dereference the work area ptr table...	pha	lda >theWapt	pha	tsc	tcd	ldy #24	lda [<1],y	; get the event manager wap	ply	; remove the handle deref	ply	cmp #0	; re-assert the zero flag...	beq DKTDone	; if zero, then event mgr not started...	tcd	; make it the current dpage...;; Now test to see if we should translate the reference	lda <ktransRef+2	; see if we need to translate	bne @1	clc	bra DKTDone	; high word of zero means no dice@1	pei ktransRef+2	; save handle	pei ktransRef	ldy #2	; deref in place	lda [ktransRef],y	tax	lda [ktransRef]	sta ktransRef	stx ktransRef+2	;; Translate the key;	lda keyMods,s	; get the modifiers byte	and #$0800	; strip off the option key	beq DoNormalKey	; if equal, then do a normalKey	bra DoOptionKeyDModDone; come here when the key modification is finished.	pla	; restore the handle	sta ktransRef	pla	sta ktransRef+2DKTDone	pld	; restore the direct page...	rts	DoOptionKey	lda keyData,s	; get the keyboard data	ora #$0080	; set the high bit	bra DNK0010	; and continueDoNormalKey	lda keyData,sDNK0010; keycode is in <A> right now...	tay	; place it in <Y>	lda [<kTransRef],y	; get the new character code	and #$00FF	; strip off high byte...;; 1/11/90 Mensch; Add the following few lines for France...; If the entry in the translation table is $FF then we must set the high bit ; of the keycode and read the table again. This allows dead keys in several layers;	cmp #$00FF	; is it a non-option deadkey?	bne @NotDead1	tya	; if its $FF then mark it as an option key	ora #$0080	; and continue...	tay	lda [<ktransRef],y	and #$00FF	; do the same as above..@NotDead1	tax	; and save it for a while...	lda <kTransFlag	; get the deadkey flag	bne  DoDeadKey2	; handle second dead key	tya	; get the original code back	and #$0080	; test to see if it was an 'option' key	beq dnk0030	; if not, then simply finish up here@TestDead	stx <kTransFlag	; save the keycode in the keytrans flag...	ldy #256	; start scanning thru the deadkey tablednk0020	lda [<kTransRef],y	; get the next key...	and #$00FF	; strip off the hi byte	beq dnk0030	; if zero, then this is done...	cmp <kTransFlag	; see if it equals our key	beq DoDeadKey1	; If in the table,  then use it...	iny	; bump Y to get the next keycode...	iny	bra dnk0020	; go back for more!dnk0030	txa	; not a dead key so recover the flag	stz <kTransFlag	; zero out the deadkeyFlag	sta keyData,s	; save it back where it belongs	clc	; set flag for good key!	bra dModDone	; finish the call... as if nothing happenedDoDeadKey1; this routine is called if a new dead key has been pressed...	sec	; set flag for bad key	bra dModDone	; and finish!DoDeadKey2; This routine is called after the next keypress after a dead key.; First find the entry offset into the dead key table for the last dead key!	ldy #256	; start scanning thru the deadkey tableddk0020	lda [<kTransRef],y	; get the next key...	and #$00FF	; strip off the hi byte	beq ddkDone	; if zero, then something bad happened just pass it on...	cmp <kTransFlag	; see if it equals our key	beq ddk0030	; If in the table,  then use it...	iny	; bump Y to get the next keycode...	iny		bra ddk0020	; go back for more!ddk0030	; we have found the number of that dead key, so now we step thru the deadkey data; tables one entry at a time till we find the proper key!	lda [<kTransRef],y	; now get the table value back...	and #$FF00	; strip off the character code and just get the offset	xba	; place the offset in the low byte	asl a	; multiply it by 2...	clc	; add 256 to it...	adc #256	; to get the offset into kTransTbl	tay	; and store it in <Y>	phx	; stow the keycode on the stack for a minuteddk0040	; This loop will walk the table of values for the current dead key, looking for the ; current keypress value	lda [<kTransRef],y	; load in the next byte	and #$00FF	; strip off the low byte	beq ddkNotValid	; take this branch if we do not find the kay in the table	cmp 1,s	; compare it to the key that was pressed..	beq ddkValid	; found a valid double key combo...	iny	iny	bra ddk0040ddkDone; If we get here then the doublekey value is in <X>, simply return it!	txa	; place the keycode in <A>	sta keyData,s	; save it back on the stack	stz <kTransFlag	; zero out the flag	clc	; set the good key flag	bra LongdModDone	; and returnddkValid; We got a valid double key code, 			plx	; recover the word we stowed ion the stack	lda [<kTransRef],y	; get the new keycode	and #$FF00	; zap off the old data	xba	; swap it!	tax	; save it in <X>	bra ddkDoneddkNotValid; This routine is called when we get a keypress that was not in the table of key presses; This will resurect the dead key and post it, then it will post the 'Live' key..	pla	; recover the keycode from the stack...	sta keyData,s	; store the data for later posting	lda keyMods,s	; get the current modifiers...	pha	; room for result...	pea $0003	; post a keydown event...	ora #$0800	; be sure to set the option bit on modifiers...	pha	lda <kTransFlag	; load the dead keycode	pha	_PostEvent	; post it as an event...	pla	; discard the result 	stz <kTransFlag	; zero out the dead key flag	clc	; clear the flag to denote a postingLongdModDone	brl dModDone		ENDP****************************************************************** Mouse Interrupt Handler*****************************************************************	EXPORT MouseMouse	PROC	LONGA on	LONGI on	rep #$30	;go into 16 bitmode	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	PushWord #0	;space for result	_ServeMouse	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	LONGA off	LONGI off	sep #$30	;go into 8 bit mode	lda >ModLatch	pha	;push mod keys latch	lda #0	pha	;push lo byte	LONGA on	LONGI on	rep #$30	;go into 16 bit mode	PushWord #0	;push 3 words for result	PushWord #0	PushWord #0	_readMouse2	IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	EXPORT Mouse2Mouse2		;       ;MouseTask jmps here	pla	;get button status	sta >EMBStat	pla	;get Y position	sta >EMYPos	pla	;get X position	sta >EMXPos;		;modlatch and servemouse result on stack	EXPORT Mouse3Mouse3		;       ;FakeMouse jmps here	lda >EMXPos	pha	lda >EMYPos	;always update cursor position in case	pha	;more than 1 pointing device being used	jsl CUpdateCheckBtns	lda 3,s	;get interrupt bits	and #BtnIntBit	;was there a button	interrupt?	bne Cont	;yes	pla	;pull mod keys latch	pla	;pull interrupt bits	bra DoneCont	jsr SetModBits	;set up modifiers word in Y	pla	;pull mod keys latch	pla	;pull interrupt bits	phy	;save Y on stack	PushWord #0	;push space to save	btn # in	PushWord #0	;push space for PostEvent result	tya	;get modifiers word	in A	and #Btn0Bit	;is button 0 currently down?	bne Btn0Up	;no	lda >EMBStat	;check previous status of btn 0	asl a	asl a	bcs CheckBtn1	;it was down so no change	PushWord #MouseDown	;it was up	lda #0	bra PostItBtn0Up	lda >EMBStat	;check previous status of btn 0	asl a	asl a	bcc CheckBtn1	;it was up so no change	PushWord #MouseUp	;it was down	lda #0	bra PostItCheckBtn1	lda 5,s	;get modifiers word	tay	and #Btn1Bit	;is btn 1 currently	down?	bne Btn1Up	;no	lda >EMBStat	;check previous status of btn 1	xba	lsr a	bcs NoChange	;it was down so no change	PushWord #MouseDown	lda #1	bra PostItBtn1Up	lda >EMBStat	;check previous status of btn 1	xba	lsr a	bcc NoChange	;it was up so no change	PushWord #MouseUp	lda #1PostIt	phy	;push modifiers - hi word of msg	pha	;push button num - lo word of msg	sta 9,s	;save button # on stack	_PostEvent	lda 3,s	;check button #	beq CheckBtn1	;if 0 - go check button 1NoChange	pla	;pull result	pla	;pull button #	pla	;pull modsDone		IF midi=1 THEN	jsl MIDIInputPoll	; Check MIDI input	ENDIF	sep #$30	;go back to 8 bit mode	LONGA off	LONGI off	clc	rtl	ENDP****************************************************************** Desk Accessory Interrupt Handler*****************************************************************	EXPORT DeskAccDeskAcc	PROC	LONGA on	LONGI on	rep #$30	;go into 16 bit mode	PushWord #0	;push result	PushWord #DeskAccessory ;Desk Accessory	event	PushWord #0	;push event message	PushWord #0	_PostEvent	pla	;pull result	sep #$30	;go back to 8 bit mode	LONGA off	LONGI off	clc	rtl	ENDP****************************************************************** Flush Buffer Interrupt Handler*****************************************************************	EXPORT FlushBufFlushBuf	PROC	LONGA on	LONGI on	rep #$30	;go into 16 bit mode	PushWord #0	;push result	PushWord #$28	;key-down and auto-key events	PushWord #0	;stop mask	_FlushEvents	pla	;pull result	sep #$30	;go back to 8 bit mode	LONGA off	LONGI off	clc	rtl	ENDP****************************************************************** Heartbeat Task for Mouse Card*****************************************************************MouseTask	PROC	LONGA on	LONGI on	rep #$30	;go into 16 bit mode	lda #1	sta >TaskHead+4	;set task counter back to 1	PushWord #0	;space for fake ServeMouse result	LONGA off	LONGI off	sep #$30	;go into 8 bit mode	lda >ModLatch	pha	;push mod keys latch	lda #0	pha	;push lo byte	LONGA on	LONGI on	rep #$30	;go into 16 bit mode	PushWord #0	;push 3 words for readMouse2 result	PushWord #0	PushWord #0	_readMouse2	ldy #0	;set change flag to	0	lda 1,s	;get BStat	and #MovedBit	;did mouse move?	beq CheckBtn0	;no	lda 9,s	;get fake ServeMouse result	ora #MoveIntBit	;fake a movement interrupt	sta 9,s	iny	;flag changeCheckBtn0	lda 1,s	;get BStat	asl a	;is btn 0 down?	bcc Btn0Up	;no	asl a	;yes - so check if was down on last read	bcc SetBtnBit	;was up so button state changed	bcs CheckBtn1	;was down so no changeBtn0Up	asl a	;was button down on	last read?	bcs SetBtnBit	;yes so state changedCheckBtn1	lda 1,s	;get BStat back	xba	tax	;save BStat	and #$10	;is btn 1 down?	beq Btn1Up	;no	txa	;yes - so check if was down on last read	lsr a	bcc SetBtnBit	;was up so button state changed	bcs Done	;was down so no changeBtn1Up	txa	lsr a	;was button down on	last read?	bcc Done	;no - so no changeSetBtnBit	lda 9,s	;get fake ServeMouse result	ora #BtnIntBit	;fake a button interrupt	sta 9,s	iny	;flag changeDone	tya	;did mouse state change?	beq Return	;no	jmp Mouse2	;jmp into mouse interrupt handlerReturn	pla	;pull stuff off stack	pla	pla	pla	pla	sep #$30	;go back to 8 bit mode	LONGA off	LONGI off	rtl	ENDP*****************************************************************SetAutoKeyLimit	PROC** Sets the AutoKeyLimit to the value passed.*** Inputs:*	NewLimit** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 30 Jun 88	Steven Glass & Cheryl Ewy** Added to allow App to set AutoKeyLimit*****************************************************************	DefineStackOrigD	wordRTL1	block 3RTL2	block 3NewLimit	word	phd	tcd	bne DoIt	ldx #ActiveErr	jml ErrOut2DoIt	lda NewLimit,s	inc a	sta <AutoKeyLimit	jml EndCall2	ENDP****************************************************************** UseCoolMousePos** 24-Feb-91 Dave Lyons** Check for MessageCenter message #6 containing the mouse* position (Y,X in 640 coordinates).** If the message is there, call FakeMouse to move the mouse* somewhere nice.  If we're in 320, we need to cut the X* coordinate in half first.*****************************************************************UseCoolMousePos	proc export	pea 0	_QDStatus	pla	beq @exit	pha	pha	;space for GetMsgHandle result	pea 1	;get message by type	pushlong #6	;message type=6	_GetMsgHandle	plx	ply*** added 3-Jun-92 DAL -- Use nonzero default position	bcc @gotMessage	ldx #defaultMsgHandle	ldy #^defaultMsgHandle@gotMessage*** end 3-Jun-92*** dereference message handle to <1	phd	phy	phx	tsc	tcd	ldy #2	lda [1],y	tax	lda [1]	sta 1	stx 3*** put Y value at 1, X value at 3	ldy #6+2	;offset to X value	lda [1],y	tax	dey	dey	lda [1],y	sta 1	stx 3*** destroy the message from MessageCenter (moved down, 3-Jun-92 DAL)	pea 3	;delete message	pea 6	;message type	pha	pha	_MessageCenter*** If we're in 320, cut X value in half	pea 0	_GetMasterSCB	pla	bcs @not320	and #$0080	bne @not320	lsr 3@not320*** do the FakeMouse call	pea 2	;flag that the XY position has changed	pea 0	;modifiers	pei 3	;X value	pei 1	;Y value	pea 0	;button states	_FakeMouse	pla	pla	pld@exit	rtl*** added 3-Jun-92 DALdefaultMsgHandle	dc.l defaultPosMsgdefaultPosMsg	dc.l 0	;link	dc.w 6	;msg type	dc.w 17,26*** end 3-Jun-92****************************************************************** CreateMouseMessage** 24-Feb-91 Dave Lyons** Create MessageCenter message #6 containing the mouse* position (Y,X, in 640 coordinates).*****************************************************************CreateMouseMessage	proc export	pha	pha	;space for new handle	pea 0	pea 6+4	;6 bytes overhead + 4 bytes data	pea $4006	;memory ID	pea 0	;attributes	pha	pha	;location (ignored)	_NewHandle	pea 1	;add message (MessageCenter parameters)	pea 6	;message type	lda 7,s	pha	lda 7,s	pha	;pushed a 2nd copy of the handle, for MessageCenter	phd	pha	pha	;space for pointer	tsc	tcd@ptr	equ 1@hndl	equ 7	pha	pha	pha	_ReadMouse	pla	;ignore stat/mode from ReadMouse*** if we're in 320, double the X value	pea 0	_GetMasterSCB	pla	bcs @not320	and #$0080	bne @not320	lda 3,s	asl a	sta 3,s@not320	ldy #2	lda [@hndl],y	sta @ptr+2	lda [@hndl]	sta @ptr	pla	;pull Y value from ReadMouse	ldy #6	;offset to Y position data in message handle	sta [@ptr],y	pla	;pull X value from ReadMouse	ldy #8	;offset to X position data in message handle	sta [@ptr],y	pla	pla	pld	_MessageCenter	;add the message	_DisposeHandle	;get rid of our copy of the handle	rtl	EndP;	Include 'EM.KBDStuff'	END